from typing import List
from bisect import bisect_right

class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        indexed = [(l, r, w, i) for i, (l, r, w) in enumerate(intervals)]
        indexed.sort(key=lambda x: x[0])
        n = len(indexed)
        starts = [x[0] for x in indexed]

        dp = [[(0, []) for _ in range(5)] for _ in range(n + 1)]

        for i in range(n - 1, -1, -1):
            l, r, w, original_idx = indexed[i]
            next_i = bisect_right(starts, r)

            for k in range(1, 5):
                skip_weight, skip_indices = dp[i + 1][k]

                take_next_weight, take_next_indices = dp[next_i][k - 1]
                take_weight = w + take_next_weight
                take_indices = sorted(take_next_indices + [original_idx])

                if take_weight > skip_weight:
                    dp[i][k] = (take_weight, take_indices)
                elif take_weight < skip_weight:
                    dp[i][k] = (skip_weight, skip_indices)
                else:
                    dp[i][k] = (take_weight, min(take_indices, skip_indices))

        return dp[0][4][1]
